function skipTodoOccurrence(id){const t=(appData.todos||[]).find(function(x){return String(x.id)===String(id);});if(!t||t.done)return false;const rr=normTodoRepeat(t.repeat);if(!rr)return false;const today=getTodayStr();const nx=nextTodoRepeatDate(Object.assign({},rr,{last:today}),today,false)||addDaysStr(today,1);t.repeat=Object.assign({},rr,{last:today,next:nx});t.skippedDate=today;t.reminded=false;saveData();UIFX.renderTodos();UIFX.toast('已跳过本次，下次 '+String(nx).slice(5).replace('-','/'));return true;}
function todoEnsureBlocks(t,settings){if(!t||typeof t!=='object')return[];if(!Array.isArray(t.blocks))t.blocks=todoBlocksOf(t,settings||appData.settings);return t.blocks;}
function todoAddBlock(id,dateStr,aMin,bMin){const t=(appData.todos||[]).find(function(x){return String(x.id)===String(id);});if(!t)return{ok:false,reason:'no-todo'};const ds=String(dateStr==null?'':dateStr).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(ds))return{ok:false,reason:'date'};let dsUse=ds;let movedTo=null;if(normTodoRepeat(t.repeat)&&!todoRepeatMatches(t.repeat,ds)){const hit=nextTodoRepeatDate(t.repeat,ds,true);if(hit&&hit!==ds){dsUse=hit;movedTo=hit;}}
const lo=Math.min(Number(aMin),Number(bMin));const hi=Math.max(Number(aMin),Number(bMin));if(!isFinite(lo)||!isFinite(hi))return{ok:false,reason:'time'};if(hi-lo<TODO_EXTRA_MIN_MIN)return{ok:false,reason:'short'};if(lo<0||hi>=TB_DAY_MINUTES)return{ok:false,reason:'range'};const list=todoEnsureBlocks(t).slice();for(let i=0;i<list.length;i++){const b=list[i];if(!b||b.start.slice(0,10)!==dsUse)continue;const bs=tbHHMMToMin(b.start);const be=tbHHMMToMin(b.end);if(bs==null||be==null)continue;if(lo<be&&bs<hi)return{ok:false,reason:'overlap',hitStart:bs,hitEnd:be,movedTo:movedTo};}
if(list.length>=TODO_EXTRA_MAX)return{ok:false,reason:'max'};list.push({start:dsUse+' '+tbMinToHHMM(lo),end:dsUse+' '+tbMinToHHMM(hi)});t.blocks=normExtraBlocks(list);saveData();return{ok:true,count:t.blocks.length,movedTo:movedTo};}
function todoRemoveBlock(id,startStr){const t=(appData.todos||[]).find(function(x){return String(x.id)===String(id);});if(!t)return false;const key=String(startStr==null?'':startStr);const list=todoEnsureBlocks(t);const next=list.filter(function(b){return b.start!==key;});if(next.length===list.length)return false;t.blocks=next;saveData();return true;}
function todoDayPlanAdd(id,dateStr,aMin,bMin){const t=(appData.todos||[]).find(function(x){return String(x.id)===String(id);});if(!t)return{ok:false,reason:'no-todo'};const ds=String(dateStr==null?'':dateStr).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(ds))return{ok:false,reason:'date'};const lo=Math.min(Number(aMin),Number(bMin));const hi=Math.max(Number(aMin),Number(bMin));if(!isFinite(lo)||!isFinite(hi))return{ok:false,reason:'time'};if(hi-lo<TODO_EXTRA_MIN_MIN)return{ok:false,reason:'short'};if(lo<0||hi>=TB_DAY_MINUTES)return{ok:false,reason:'range'};if(!t.dayPlan||typeof t.dayPlan!=='object'||Array.isArray(t.dayPlan))t.dayPlan={};const list=(t.dayPlan[ds]||[]).slice();for(let i=0;i<list.length;i++){const bs=tbHHMMToMin(list[i].start);const be=tbHHMMToMin(list[i].end);if(bs==null||be==null)continue;if(lo<be&&bs<hi)return{ok:false,reason:'overlap',hitStart:bs,hitEnd:be};}
if(list.length>=TODO_EXTRA_MAX)return{ok:false,reason:'max'};const wasEmpty=!list.length;list.push({start:ds+' '+tbMinToHHMM(lo),end:ds+' '+tbMinToHHMM(hi)});t.dayPlan[ds]=normExtraBlocks(list);saveData();return{ok:true,count:t.dayPlan[ds].length,replaced:wasEmpty};}
function todoDayPlanSet(id,dateStr,segs){const t=(appData.todos||[]).find(function(x){return String(x.id)===String(id);});if(!t)return{ok:false,reason:'no-todo'};const ds=String(dateStr==null?'':dateStr).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(ds))return{ok:false,reason:'date'};const clean=normExtraBlocks(segs).filter(function(b){return b.start.slice(0,10)===ds;});if(!clean.length)return{ok:false,reason:'empty'};if(!t.dayPlan||typeof t.dayPlan!=='object'||Array.isArray(t.dayPlan))t.dayPlan={};t.dayPlan[ds]=clean;saveData();return{ok:true,count:clean.length};}
function todoDayPlanClear(id,dateStr){const t=(appData.todos||[]).find(function(x){return String(x.id)===String(id);});if(!t||!t.dayPlan||typeof t.dayPlan!=='object')return false;const ds=String(dateStr==null?'':dateStr).slice(0,10);if(!t.dayPlan[ds])return false;delete t.dayPlan[ds];if(!Object.keys(t.dayPlan).length)delete t.dayPlan;saveData();return true;}
