const COIN_LOG_MAX=500;function coinLedgerEnsure(){const tr=appData&&appData.tree;if(!tr)return[];if(!Array.isArray(tr.coinLog))tr.coinLog=[];return tr.coinLog;}
function coinLedgerInit(){const tr=appData&&appData.tree;if(!tr)return[];const log=coinLedgerEnsure();if(tr.coinLogInit)return log;tr.coinLogInit=true;const diff=coinLedgerDiff(log,tr.coins);if(diff!==0){const first=log[0];log.unshift(coinTxMake({type:'opening',amount:diff,after:diff,at:first?Number(first.at)-1:Date.now(),reason:'期初结转（记账功能上线时的余额）'}));}
return log;}
function coinLedgerPush(tx){const log=coinLedgerEnsure();log.push(tx);if(log.length>COIN_LOG_MAX)coinLedgerCompact();return tx;}
function coinLedgerCompact(){const log=appData.tree&&appData.tree.coinLog;if(!Array.isArray(log)||log.length<=COIN_LOG_MAX)return;const keep=COIN_LOG_MAX-1;const cutCount=log.length-keep;const cut=log.slice(0,cutCount);const last=cut[cut.length-1];const carried=coinTxMake({type:'opening',amount:coinLedgerSum(cut),after:last.after,at:last.at,reason:'结转（更早 '+cutCount+' 笔已合并）'});appData.tree.coinLog=[carried].concat(log.slice(cutCount));}
