function coinUndo(txId){const log=coinLedgerInit();const id=String(txId);if(!coinTxUndoable(log,id))return false;const hit=log.filter(function(t){return String(t.id)===id;})[0];if(!hit)return false;const back=-hit.amount;if(back<0&&(Number(appData.tree.coins)||0)<Math.abs(back))return false;appData.tree.coins=(Number(appData.tree.coins)||0)+back;coinLedgerPush(coinTxMake({type:'undo',amount:back,after:appData.tree.coins,undoOf:id,reason:'撤销：'+(hit.reason||coinTxTypeLabel(hit.type)),meta:{undoneType:hit.type}}));saveData();return true;}
