function getDynamicMult(coins){coins=coins||0;if(coins<=300)return 1;if(coins<4000)return 1+((coins-300)/3700)*1.0;if(coins<8000)return 2+((coins-4000)/4000)*1.0;return 3;}
function getDynamicPrice(base,coins){const m=getDynamicMult(coins);return Math.max(1,Math.round((base*m)/5)*5);}
